(function(){const G = window.__game, A = G.Air.s, K = G.Keys, TH = G.THREE_;
G.save.set.dev = true; G.save.set.cycle = 0;
const msgs = []; G.UI.toast = (t, k) => { msgs.push('T:' + t); }; G.UI.banner = (k, t) => { msgs.push('B:' + k + ' ' + t); };
G.UI.devAct('tpair'); for (let i = 0; i < 40; i++) G.Chunks.update(A.cx - 150, A.cz + 60, 3);
G.Foot.exit();
const out = [];
const sp = G.Fly.planes.find(p => p.id === 'sparrow'), vx = G.Fly.planes.find(p => p.id === 'vixen'), tl = G.Fly.planes.find(p => p.id === 'talon');
const walkTo = (P) => { G.Foot.on = true; G.Foot.x = P.x + 3.0; G.Foot.z = P.z; G.Foot.y = P.y - P.spec.cgY; G.Foot.state = 'walk'; G.Fly.scan(); return G.Fly.near && G.Fly.near.id; };
out.push('near sparrow: ' + walkTo(sp)); G.Fly.useNear(); out.push('on=' + G.Fly.on + ' foot=' + G.Foot.on + ' body=' + document.body.className);
// try exit while moving
sp.vz = -10; sp.vx = 0; sp.gnd = true; sp.gt = 0.1; sp.speed = 10; G.Fly.exit(); out.push('exit while moving: on=' + G.Fly.on);
sp.vz = 0; sp.speed = 0; G.Fly.exit(); out.push('exit stopped: on=' + G.Fly.on + ' foot=' + G.Foot.on + ' body=' + document.body.className + ' st=' + sp.st);
out.push('near again: ' + walkTo(sp)); G.Fly.useNear(); out.push('reboard on=' + G.Fly.on);
G.Fly.reset(); out.push('reset ok st=' + sp.st); G.Fly.exit();
// purchase
G.save.money = 100; out.push('near vixen: ' + walkTo(vx)); G.Fly.useNear(); out.push('poor: on=' + G.Fly.on + ' own=' + !!G.save.air.own.vixen + ' money=' + G.save.money);
G.save.money = 5000; G.Fly.useNear(); out.push('rich: on=' + G.Fly.on + ' own=' + !!G.save.air.own.vixen + ' money=' + G.save.money + ' tag=' + !!vx.tag);
G.Fly.exit();
const raw = JSON.parse(localStorage.getItem('island-rush-v1')); out.push('saved own=' + JSON.stringify(raw.air.own) + ' money=' + raw.money);
// wanted blocks boarding
G.Wanted.set(2); out.push('near talon: ' + walkTo(tl)); G.save.air.own.talon = true; G.Fly.tags(); G.Fly.useNear(); out.push('wanted: on=' + G.Fly.on); G.Wanted.set(0);
// respawn while flying
G.Fly.useNear(); out.push('talon on=' + G.Fly.on); G.UI.devAct('tp0'); out.push('after tp: fly=' + G.Fly.on + ' foot=' + G.Foot.on + ' talon st=' + tl.st + ' body=' + document.body.className);
// key handling while flying
G.UI.devAct('tpair'); for (let i = 0; i < 10; i++) G.Chunks.update(A.cx - 150, A.cz + 60, 3); G.Foot.exit(); walkTo(sp); G.Fly.useNear();
const before = G.save.set.fassist; G.Keys.KeyH = true; G.UI.devAct; 
return out.join('\n') + '\n' + msgs.join('\n');})()
